#!/usr/bin/env python3
"""One-off decode helper — run once to produce data/districts.csv."""
import base64
import gzip
import pathlib

B64 = (
    ""
)

if __name__ == "__main__":
    pad = (-len(B64)) % 4
    out = gzip.decompress(base64.b64decode(B64 + "=" * pad))
    pathlib.Path(__file__).resolve().parent.parent.joinpath("data/districts.csv").write_bytes(out)
    print("wrote", len(out), "bytes")
